@section('content')<div class="page-heading"><div><span class="eyebrow">ACCOUNTABILITY</span><h1>Activity log</h1><p>Recorded actions for sales, stock, purchases, returns, expenses, payments and staff access.</p></div></div><section class="panel"><div class="panel-heading"><div><h2>Recent activity</h2><p>Audit rows are written with their business transaction.</p></div></div>@if($logs->isEmpty())<div class="empty-state"><div class="empty-icon">◷</div><b>No recorded actions yet</b></div>@else<div class="table-wrap"><table><thead><tr><th>WHEN</th><th>USER</th><th>ACTION</th><th>RECORD</th><th>DETAILS</th></tr></thead><tbody>@foreach($logs as $log)<tr><td>{{ $log->created_at->format('d M Y, h:i A') }}</td><td>{{ $log->user?->name ?? 'System' }}</td><td class="table-primary">{{ ucwords(str_replace(['.','_'],[' ',' '],$log->action)) }}</td><td>{{ class_basename($log->subject_type) }} #{{ $log->subject_id }}</td><td>{{ collect($log->details)->map(fn($v,$k)=>$k.': '.(is_scalar($v)?$v:json_encode($v)))->join(' · ') ?: '—' }}</td></tr>@endforeach</tbody></table></div><div class="pagination">{{ $logs->links() }}</div>@endif</section>@endsection
